import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PhoneInput from '../../components/common/PhoneInput/PhoneInput';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import styles from './ProfilePage.module.css';

const ProfilePage = () => {
    const { user, updateProfile, changePassword, deleteAccount, logout } = useAuth();
    const [profile, setProfile] = useState({
        name: user?.name || '',
        email: user?.email || '',
        phone: user?.phone || '',
        gameLevel: user?.gameLevel || 'D2',
        language: user?.language || 'ru',
        theme: user?.theme || 'light'
    });
    const [passwords, setPasswords] = useState({ current: '', new: '', confirm: '' });
    const [profileErrors, setProfileErrors] = useState({});
    const [passwordErrors, setPasswordErrors] = useState([]);
    const [passwordStrength, setPasswordStrength] = useState({ valid: false, errors: [] });
    const [loading, setLoading] = useState(false);
    const [loadingPassword, setLoadingPassword] = useState(false);
    const [message, setMessage] = useState({ text: '', type: '' });
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    const validateName = (name) => {
        if (!name) return 'Имя обязательно';
        if (name.length < 2) return 'Имя должно содержать минимум 2 символа';
        if (name.length > 100) return 'Имя не должно превышать 100 символов';
        const nameRegex = /^[A-Za-zА-Яа-я\s]+$/;
        if (!nameRegex.test(name)) return 'Имя может содержать только буквы и пробелы';
        return '';
    };

    const validateEmail = (email) => {
        if (!email) return 'Email обязателен';
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) return 'Введите корректный email (example@domain.com)';
        return '';
    };

    const validatePhone = (phone) => {
        if (!phone) return '';
        const phoneRegex = /^\+375 \d{2} \d{3}-\d{2}-\d{2}$/;
        if (!phoneRegex.test(phone)) return 'Телефон должен быть в формате +375 XX XXX-XX-XX';
        const digits = phone.replace(/\D/g, '');
        if (digits.length !== 12) return 'Введите полный номер телефона (9 цифр после кода)';
        return '';
    };

    const validateGameLevel = (level) => {
        if (!level) return 'Выберите уровень игры';
        return '';
    };

    const validatePasswordStrength = (password) => {
        const errorsList = [];
        if (password.length < 8) errorsList.push('минимум 8 символов');
        const hasUpperLatin = /[A-Z]/.test(password);
        const hasUpperCyrillic = /[А-ЯЁ]/.test(password);
        if (!hasUpperLatin && !hasUpperCyrillic) errorsList.push('заглавную букву (A-Z или А-Я)');
        const hasLowerLatin = /[a-z]/.test(password);
        const hasLowerCyrillic = /[а-яё]/.test(password);
        if (!hasLowerLatin && !hasLowerCyrillic) errorsList.push('строчную букву (a-z или а-я)');
        if (!/[0-9]/.test(password)) errorsList.push('цифру (0-9)');
        if (!/[!@#$%^&*]/.test(password)) errorsList.push('спецсимвол (!@#$%^&*)');
        return errorsList;
    };

    const validateCurrentPassword = (password) => {
        if (!password) return 'Введите текущий пароль';
        return '';
    };

    useEffect(() => {
        const errors = validatePasswordStrength(passwords.new);
        setPasswordStrength({ valid: errors.length === 0, errors });
        if (passwords.confirm && passwords.new !== passwords.confirm) {
            setPasswordErrors(['Пароли не совпадают']);
        } else {
            setPasswordErrors([]);
        }
    }, [passwords.new, passwords.confirm]);

    const validateProfileForm = () => {
        const newErrors = {
            name: validateName(profile.name),
            email: validateEmail(profile.email),
            phone: validatePhone(profile.phone),
            gameLevel: validateGameLevel(profile.gameLevel)
        };
        setProfileErrors(newErrors);
        return Object.values(newErrors).every(error => error === '');
    };

    const validatePasswordForm = () => {
        const currentError = validateCurrentPassword(passwords.current);
        if (currentError) {
            setPasswordErrors([currentError]);
            return false;
        }
        if (!passwordStrength.valid) {
            setPasswordErrors(passwordStrength.errors);
            return false;
        }
        if (passwords.new !== passwords.confirm) {
            setPasswordErrors(['Пароли не совпадают']);
            return false;
        }
        return true;
    };

    const handleSaveProfile = async (e) => {
        e.preventDefault();
        if (!validateProfileForm()) return;
        setLoading(true);
        try {
            await updateProfile(profile);
            setMessage({ text: 'Профиль успешно обновлен', type: 'success' });
            setTimeout(() => setMessage({ text: '', type: '' }), 3000);
        } catch (err) {
            setMessage({ text: err.message || 'Ошибка обновления', type: 'error' });
        } finally {
            setLoading(false);
        }
    };

    const handleChangePassword = async (e) => {
        e.preventDefault();
        if (!validatePasswordForm()) return;
        setLoadingPassword(true);
        try {
            await changePassword({ currentPassword: passwords.current, newPassword: passwords.new });
            setMessage({ text: 'Пароль успешно изменен', type: 'success' });
            setPasswords({ current: '', new: '', confirm: '' });
            setTimeout(() => setMessage({ text: '', type: '' }), 3000);
        } catch (err) {
            setMessage({ text: err.message || 'Ошибка смены пароля', type: 'error' });
        } finally {
            setLoadingPassword(false);
        }
    };

    const handleDeleteAccount = async () => {
        if (window.confirm('Вы уверены? Это действие необратимо!')) await deleteAccount();
    };

    const handleFieldChange = (field, value) => {
        setProfile({ ...profile, [field]: value });
        let error = '';
        if (field === 'name') error = validateName(value);
        if (field === 'email') error = validateEmail(value);
        if (field === 'phone') error = validatePhone(value);
        if (field === 'gameLevel') error = validateGameLevel(value);
        setProfileErrors({ ...profileErrors, [field]: error });
        if (message.text) setMessage({ text: '', type: '' });
    };

    const handlePhoneChange = (e) => {
        const value = e.target.value;
        setProfile({ ...profile, phone: value });
        const error = validatePhone(value);
        setProfileErrors({ ...profileErrors, phone: error });
    };

    const handleLanguageChange = (lang) => {
        setProfile({ ...profile, language: lang });
        if (message.text) setMessage({ text: '', type: '' });
    };

    const handleThemeChange = (theme) => {
        setProfile({ ...profile, theme: theme });
        if (message.text) setMessage({ text: '', type: '' });
    };

    const getGameLevelDisplay = (level) => {
        return level === 'D4Plus' ? 'D4+' : level;
    };

    // Для отладки - выводим текущий уровень из БД
    console.log('Current user gameLevel from DB:', user?.gameLevel);
    console.log('Current profile gameLevel:', profile.gameLevel);

    return (
        <div className={styles.profilePage}>
            <div className={styles.container}>
                <div className={styles.profileCard}>
                    <div className={styles.header}>
                        <h1 className={styles.title}>Личный кабинет</h1>
                    </div>
                    <div className={styles.content}>
                        {message.text && <div className={`${styles.message} ${styles[message.type]}`}>{message.text}</div>}

                        <form onSubmit={handleSaveProfile} className={styles.form}>
                            <div className={styles.fieldGroup}>
                                <Input
                                    label="Имя"
                                    value={profile.name}
                                    onChange={(e) => handleFieldChange('name', e.target.value)}
                                    required
                                />
                                {profileErrors.name && <span className={styles.fieldError}>{profileErrors.name}</span>}
                            </div>

                            <div className={styles.fieldGroup}>
                                <Input
                                    label="Email"
                                    type="email"
                                    value={profile.email}
                                    onChange={(e) => handleFieldChange('email', e.target.value)}
                                    required
                                />
                                {profileErrors.email && <span className={styles.fieldError}>{profileErrors.email}</span>}
                            </div>

                            <div className={styles.fieldGroup}>
                                <PhoneInput
                                    label="Телефон"
                                    value={profile.phone}
                                    onChange={handlePhoneChange}
                                    error={profileErrors.phone}
                                />
                            </div>

                            <div className={styles.levelSection}>
                                <label className={styles.label}>Уровень игры</label>
                                <div className={styles.levelButtons}>
                                    {levels.map(level => (
                                        <ToggleButton
                                            key={level}
                                            label={getGameLevelDisplay(level)}
                                            isActive={profile.gameLevel === level}
                                            onClick={() => handleFieldChange('gameLevel', level)}
                                        />
                                    ))}
                                </div>
                                {profileErrors.gameLevel && <span className={styles.fieldError}>{profileErrors.gameLevel}</span>}
                            </div>

                            <Button type="submit" fullWidth loading={loading}>Сохранить изменения</Button>
                        </form>

                        <form onSubmit={handleChangePassword} className={styles.passwordForm}>
                            <h3 className={styles.sectionTitle}>Смена пароля</h3>

                            <div className={styles.fieldGroup}>
                                <PasswordInput
                                    label="Текущий пароль"
                                    value={passwords.current}
                                    onChange={(e) => setPasswords({...passwords, current: e.target.value})}
                                    required
                                />
                            </div>

                            <div className={styles.fieldGroup}>
                                <PasswordInput
                                    label="Новый пароль"
                                    value={passwords.new}
                                    onChange={(e) => setPasswords({...passwords, new: e.target.value})}
                                    required
                                />
                                {passwords.new && passwordStrength.errors.length > 0 && (
                                    <div className={styles.passwordHintError}>
                                        Пароль должен содержать: {passwordStrength.errors.join(', ')}
                                    </div>
                                )}
                                {passwords.new && passwordStrength.valid && (
                                    <div className={styles.passwordHintSuccess}>✓ Надёжный пароль</div>
                                )}
                            </div>

                            <div className={styles.fieldGroup}>
                                <PasswordInput
                                    label="Подтверждение пароля"
                                    value={passwords.confirm}
                                    onChange={(e) => setPasswords({...passwords, confirm: e.target.value})}
                                    required
                                />
                            </div>

                            {passwordErrors.length > 0 && (
                                <div className={styles.passwordHintError}>
                                    {passwordErrors.join(', ')}
                                </div>
                            )}

                            <Button type="submit" variant="secondary" fullWidth loading={loadingPassword}>Изменить пароль</Button>
                        </form>

                        <div className={styles.settingsSection}>
                            <h3 className={styles.sectionTitle}>Настройки</h3>

                            <div className={styles.settingItem}>
                                <span className={styles.settingLabel}>Язык</span>
                                <div className={styles.settingControls}>
                                    <ToggleButton
                                        label="Русский"
                                        isActive={profile.language === 'ru'}
                                        onClick={() => handleLanguageChange('ru')}
                                    />
                                    <ToggleButton
                                        label="English"
                                        isActive={profile.language === 'en'}
                                        onClick={() => handleLanguageChange('en')}
                                    />
                                </div>
                            </div>

                            <div className={styles.settingItem}>
                                <span className={styles.settingLabel}>Тема</span>
                                <div className={styles.settingControls}>
                                    <ToggleButton
                                        label="Светлая"
                                        isActive={profile.theme === 'light'}
                                        onClick={() => handleThemeChange('light')}
                                    />
                                    <ToggleButton
                                        label="Темная"
                                        isActive={profile.theme === 'dark'}
                                        onClick={() => handleThemeChange('dark')}
                                    />
                                </div>
                            </div>
                        </div>

                        <div className={styles.actions}>
                            <Button variant="secondary" onClick={logout}>Сменить пользователя</Button>
                            <Button variant="danger" onClick={handleDeleteAccount}>Удалить аккаунт</Button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProfilePage;
